function validate([root]) {
  if (!Array.isArray(root)) return 'Write the tree as a level-order list.';
  if (root.length > 0 && root[0] === null) return 'Write an empty tree as [].';
  const values = root.filter(v => v !== null);
  if (values.length > 10000) return 'The tree has at most 10^4 nodes.';
  if (values.some(v => !Number.isInteger(v) || v < -10000 || v > 10000)) return 'Each node value is a whole number from -10^4 to 10^4.';
  let open = 1;
  for (const v of root) {
    if (open === 0) return 'Every value after the root needs a parent node.';
    open += v === null ? -1 : 1;
  }
  return null;
}

