function largestBSTSubtree(root) {
  let best = 0;

  function visit(node) {
    if (!node) {
      return { isBST: true, size: 0, min: Infinity, max: -Infinity };
    }
    const left = visit(node.left);
    const right = visit(node.right);
    if (left.isBST && right.isBST && left.max < node.val && node.val < right.min) {
      const size = left.size + right.size + 1;
      best = Math.max(best, size);
      return {
        isBST: true,
        size,
        min: Math.min(left.min, node.val),
        max: Math.max(right.max, node.val),
      };
    }
    return { isBST: false, size: 0, min: 0, max: 0 };
  }

  visit(root);
  return best;
}

