function largestBSTSubtree(root) {
  // For every node, list its subtree in in-order and check that the list strictly increases.
  const all = [];
  const stack = root ? [root] : [];
  while (stack.length) {
    const node = stack.pop();
    all.push(node);
    if (node.left) stack.push(node.left);
    if (node.right) stack.push(node.right);
  }
  let best = 0;
  for (const top of all) {
    const values = [];
    const pending = [];
    let cur = top;
    while (cur || pending.length) {
      while (cur) { pending.push(cur); cur = cur.left; }
      cur = pending.pop();
      values.push(cur.val);
      cur = cur.right;
    }
    let increasing = true;
    for (let i = 1; i < values.length; i++) if (values[i - 1] >= values[i]) increasing = false;
    if (increasing) best = Math.max(best, values.length);
  }
  return best;
}

