function generate(rand, size) {
  const pick = k => Math.floor(rand() * k);
  const large = size === 'large';
  const count = large ? 900 + pick(90) : pick(12);
  if (count === 0) return [[]];
  const deep = rand() < (large ? 0.15 : 0.3);
  const nodes = [{ val: 0, left: null, right: null }];
  while (nodes.length < count) {
    const parent = deep ? nodes[Math.max(0, nodes.length - 1 - pick(2))] : nodes[pick(nodes.length)];
    const side = rand() < 0.5 ? 'left' : 'right';
    if (parent[side]) continue;
    const node = { val: 0, left: null, right: null };
    parent[side] = node;
    nodes.push(node);
  }
  // Number the nodes in in-order with rising values so the whole tree starts as a BST...
  const stack = [];
  let cur = nodes[0];
  let value = large ? -10000 + pick(1000) : -10 + pick(6);
  while (cur || stack.length) {
    while (cur) { stack.push(cur); cur = cur.left; }
    cur = stack.pop();
    cur.val = value;
    value += large ? 1 + pick(15) : pick(4);
    cur = cur.right;
  }
  // ...then break it in a few random places.
  const breaks = large ? pick(40) : pick(4);
  for (let b = 0; b < breaks; b++) {
    nodes[pick(nodes.length)].val = large ? pick(20001) - 10000 : pick(31) - 15;
  }
  if (!large && rand() < 0.1) nodes[pick(nodes.length)].val = rand() < 0.5 ? -10000 : 10000;
  const out = [];
  const queue = [nodes[0]];
  for (let q = 0; q < queue.length; q++) {
    const node = queue[q];
    out.push(node ? node.val : null);
    if (node) queue.push(node.left, node.right);
  }
  while (out[out.length - 1] === null) out.pop();
  return [out];
}
